// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.contactimport androidx.room.ColumnInfoimport androidx.room.Daoimport androidx.room.Entityimport androidx.room.Fts4import androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.PrimaryKeyimport androidx.room.Queryimport com.roshan.persona.connectivity.model.ContactInfoimport timber.log.Timber/** * NOUS — Contact FTS Mirror (Module 11 v3 — P1). * * Strategy §"ContactSearcher" — `< 20ms / 10K contacts` requires FTS4 indexing. * Mirrors the device's ContactsContract rows into a Room FTS4 virtual table * so queries like "Mom mobile" tokenize into `name MATCH "Mom"` AND * `notes MATCH "mobile"` instead of O(N) Levenshtein scans. * * ## Refresh strategy * * - [ContactFtsSyncWorker] (OneTimeWorkRequest) rebuilds the mirror on demand. * - [ContactObserver] (ContentObserver on `ContactsContract.Contacts.CONTENT_URI`) *   triggers the worker whenever the system contacts change. * * ## Multi-field search * * The FTS table has 3 columns: `name`, `phone`, `notes`. A query like * "Mom mobile" is parsed into: * * ``` *   SELECT contact_id FROM contact_fts *   WHERE contact_fts MATCH 'name:Mom AND notes:mobile' *   LIMIT 10 * ``` * * This matches the strategy example ("Mom mobile" → name="Mom", label="mobile"). */@Entity(tableName = "contact_fts")@Fts4data class ContactFtsEntity(    /**     * FTS4 entities in Room require a primary key named `rowid` of INTEGER     * affinity. We use a stable hash of the contact ID as the rowid, and     * store the actual string contact ID in [contactId] for joining back     * to ContactsContract.     */    @PrimaryKey    @ColumnInfo(name = "rowid")    val rowid: Long,    @ColumnInfo(name = "contact_id")    val contactId: String,    @ColumnInfo(name = "name")    val name: String,    @ColumnInfo(name = "phone")    val phone: String,    @ColumnInfo(name = "notes")    val notes: String,)@Daointerface ContactFtsDao {    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun upsertAll(entities: List<ContactFtsEntity>)    /**     * Multi-field FTS4 search. The [query] string is parsed into per-field     * clauses by [parseMultiFieldQuery] before being passed to MATCH.     *     * Returns matching `contact_id`s — the caller ([ContactSearcher]) joins     * back against the live ContactsContract for fresh display names.     */    @Query(        """        SELECT contact_id FROM contact_fts        WHERE contact_fts MATCH :matchQuery        LIMIT :limit        """,    )    suspend fun search(matchQuery: String, limit: Int = 10): List<String>    @Query("DELETE FROM contact_fts")    suspend fun clear(): Int    @Query("SELECT COUNT(*) FROM contact_fts")    suspend fun count(): Int}/** * Parses a free-form user query ("Mom mobile") into a multi-field FTS4 * MATCH expression (`name:Mom AND notes:mobile`). * * Heuristic: *  1. Tokenize the query on whitespace. *  2. If the first token looks like a name (alphabetic), assign it to `name:`. *  3. Remaining tokens get OR'd across `phone:` and `notes:` (so "mobile" *     matches a phone label or a contact note). *  4. If the first token is all digits, treat the whole query as a phone prefix. * * The result is quoted to prevent FTS4 syntax-injection — only word * characters are kept. */object ContactFtsQueryParser {    /**     * Build the FTS4 MATCH expression for [query].     *     * Returns `null` if the query has no usable tokens (caller falls back     * to the legacy in-memory Levenshtein scan).     */    fun parse(query: String): String? {        val tokens = query.trim()            .split(Regex("\\s+"))            .filter { it.isNotBlank() }            .map { sanitize(it) }            .filter { it.isNotEmpty() }        if (tokens.isEmpty()) return null        // All-digit → phone prefix.        if (tokens.all { it.matches(Regex("\\d+")) }) {            return "phone:${tokens.joinToString("")}*"        }        val clauses = mutableListOf<String>()        // First token (if alphabetic) → name.        val nameToken = tokens.firstOrNull { it.first().isLetter() }        if (nameToken != null) {            clauses.add("name:$nameToken*")        }        // Remaining tokens → notes OR phone (multi-field).        for (tok in tokens.drop(if (nameToken != null) 1 else 0)) {            clauses.add("(notes:$tok* OR phone:$tok*)")        }        if (clauses.isEmpty()) return null        return clauses.joinToString(" AND ")    }    /** Strip FTS4 syntax characters — keep word chars + digits only. */    private fun sanitize(token: String): String =        token.filter { it.isLetterOrDigit() }}/** * In-memory fallback FTS searcher — used when Room is not yet initialized * (e.g., during onboarding before the first sync). Iterates contacts and * applies the same multi-field logic. */class InMemoryContactFtsSearcher {    /**     * Search [contacts] for [query] — returns matching contact IDs.     */    fun search(contacts: List<ContactInfo>, query: String, limit: Int = 10): List<String> {        val tokens = query.trim().lowercase().split(Regex("\\s+")).filter { it.isNotBlank() }        if (tokens.isEmpty()) return emptyList()        val results = mutableListOf<Pair<String, Float>>()        for (contact in contacts) {            val nameLower = contact.displayName.lowercase()            val phoneDigits = contact.phoneNumbers.joinToString("") { it.filter { d -> d.isDigit() } }            val notes = contact.email.orEmpty().lowercase() // simplified — real notes would come from ContactsContract.Note            var score = 0f            for ((idx, token) in tokens.withIndex()) {                val weight = if (idx == 0) 1.0f else 0.5f // first token more important                if (nameLower.contains(token)) score += weight                if (phoneDigits.contains(token)) score += weight                if (notes.contains(token)) score += weight * 0.5f            }            if (score > 0f) {                results.add(contact.id to score)            }        }        return results.sortedByDescending { it.second }.take(limit).map { it.first }    }    private companion object {        private const val TAG = "InMemoryContactFts"    }}